if(code===401)throw Error('GMAIL_TECH_CONSENT_REQUIRED');
if(code===403){
  var rejection={};try{rejection=JSON.parse(response.getContentText()).error||{};}catch(_){}
  var reasons=(Array.isArray(rejection.errors)?rejection.errors:[]).map(function(x){return x&&x.reason;});
  var details=(Array.isArray(rejection.details)?rejection.details:[]).map(function(x){return x&&x.reason;});
  if(reasons.indexOf('accessNotConfigured')>=0||details.indexOf('SERVICE_DISABLED')>=0)
    throw Error('GMAIL_SERVICE_DISABLED');
  if(reasons.indexOf('insufficientPermissions')>=0||details.indexOf('ACCESS_TOKEN_SCOPE_INSUFFICIENT')>=0)
    throw Error('GMAIL_TECH_CONSENT_REQUIRED');
  throw Error('GMAIL_TECH_FORBIDDEN');
}
